steps.script:
GameState.state["factions"]["2"]["detachment"] = "Flyboyz"
StratagemManager.load_faction_stratagems_for_player(2)
var spots = {"U_DAKKAJET_A": Vector2(41, 35), "U_CUSTODIAN_GUARD_F": Vector2(41, 24)}
for uid in spots:
	var u = GameState.state["units"][uid]
	var c = Vector2.ZERO
	for m in u["models"]:
		c += Vector2(float(m["position"]["x"]), float(m["position"]["y"]))
	c /= u["models"].size()
	var d = spots[uid] * 40.0 - c
	for m in u["models"]:
		m["position"] = {"x": float(m["position"]["x"]) + d.x, "y": float(m["position"]["y"]) + d.y}
var jet = GameState.state["units"]["U_DAKKAJET_A"]
jet["models"][0]["current_wounds"] = 1
jet["meta"]["stats"]["toughness"] = 2
jet["meta"]["stats"]["save"] = 7
SettingsService.auto_allocate_wounds = true
GameState.state["players"]["1"]["cp"] = 4
GameState.state["players"]["2"]["cp"] = 4
SceneRefs.main()._recreate_unit_visuals()
for c in tree.root.get_children():
	if c is Window and c != tree.root:
		c.hide()
		c.queue_free()
return StratagemManager.find_faction_stratagem_by_name(2, "FLYIN' HEADBUTT")

var by_weapon = {}
var weapons = RulesEngine.get_unit_weapons("U_CUSTODIAN_GUARD_F", GameState.state)
for mid in weapons:
	for wid in weapons[mid]:
		var prof = RulesEngine.get_weapon_profile(wid, GameState.state)
		if prof.is_empty() or float(prof.get("range", 0)) <= 0.0:
			continue
		if not by_weapon.has(wid):
			by_weapon[wid] = []
		by_weapon[wid].append(mid)
var assignments = []
for wid in by_weapon:
	assignments.append({"weapon_id": wid, "target_unit_id": "U_DAKKAJET_A", "model_ids": by_weapon[wid]})
var r = PhaseManager.get_current_phase_instance().execute_action({"type": "SHOOT", "actor_unit_id": "U_CUSTODIAN_GUARD_F", "player": 1, "payload": {"assignments": assignments, "rng_seed": 5}})
return r.get("success", false)

var rec = GameState.get_unit("U_DAKKAJET_A")["flags"]["ork11e_flyin_headbutt"]
var fours = 0
for r in rec["rolls"]:
	if int(r) >= 4:
		fours += 1
var w = 0
for m in GameState.get_unit("U_CUSTODIAN_GUARD_F")["models"]:
	if m.get("alive", true):
		w += int(m.get("current_wounds", 4))
return fours == int(rec["mortal_wounds"]) and 20 - w == fours and rec["enemy_unit_id"] == "U_CUSTODIAN_GUARD_F"
